//! Independent published TLS 1.3 record known answer, RFC 8448 section 3.
//! Expected ciphertext is copied from the RFC, never generated by our provider.
use tls_core::handshake::{Reassembler, Status};
use tls_core::protected::{ContentType, MAX_INNER_PLAINTEXT, ProtectedReader, ProtectedWriter};
use tls_core::wire::Parse;
use tls_crypto::{CipherSuite, CryptoProvider};
use tls_crypto_awslc::AwsLcProvider;

fn hex(text: &str) -> Vec<u8> {
    text.split_whitespace()
        .map(|octet| {
            assert_eq!(octet.len(), 2);
            u8::from_str_radix(octet, 16).unwrap()
        })
        .collect()
}

#[test]
fn published_server_handshake_record_and_exact_message_bytes() {
    let payload = hex(include_str!(
        "fixtures/rfc8448_server_handshake_payload.hex"
    ));
    let published_record = hex(include_str!("fixtures/rfc8448_server_handshake_record.hex"));
    assert_eq!(payload.len(), 657);
    assert_eq!(published_record.len(), 679);
    assert_eq!(&published_record[..5], &[23, 3, 3, 2, 0xa2]);

    // RFC 8448 section 3, {server} derive write traffic keys for handshake data:
    // These already-derived public test keys/IVs are source inputs, not HKDF output
    // computed by the adapter under test. AES128GCM, sequence 0, no zero padding.
    let key = hex("3f ce 51 60 09 c2 17 27 d0 f2 e4 e8 6e e4 03 bc");
    let iv: [u8; 12] = hex("5d 31 3e b2 67 12 76 ee 13 00 0b 30")
        .try_into()
        .unwrap();
    let suite = CipherSuite::Aes128GcmSha256;
    let mut writer = ProtectedWriter::new(
        AwsLcProvider.aead_key(suite, &key).unwrap(),
        iv,
        MAX_INNER_PLAINTEXT,
        suite.sending_record_limit(),
    )
    .unwrap();
    let mut encoded = vec![0xa5; published_record.len()];
    assert_eq!(writer.next_sequence(), 0);
    let written = writer
        .seal(ContentType::Handshake, &payload, 0, &mut encoded)
        .unwrap();
    assert_eq!(written, 679);
    assert_eq!(encoded, published_record);
    assert_eq!(writer.next_sequence(), 1);

    // Independently decrypt the RFC's ciphertext, not the writer's new output.
    let mut reader = ProtectedReader::new(
        AwsLcProvider.aead_key(suite, &key).unwrap(),
        iv,
        MAX_INNER_PLAINTEXT,
    )
    .unwrap();
    let mut plaintext = vec![0xa5; published_record.len()];
    let Parse::Complete { value, consumed } =
        reader.open(&published_record, &mut plaintext).unwrap()
    else {
        panic!("complete published record must decrypt");
    };
    assert_eq!(consumed, published_record.len());
    assert_eq!(value.content_type, ContentType::Handshake);
    assert_eq!(value.content, payload);
    assert_eq!(reader.next_sequence(), 1);

    // Reassemble actual authenticated bytes with bounded progress. These are
    // syntactic messages; no certificate/signature/Finished validation is claimed.
    for work_budget in [1, 17, 128, 1024] {
        let mut scratch = [0xa5; 445]; // Largest encoded message is Certificate.
        let mut reassembler = Reassembler::new(&mut scratch, 441, work_budget).unwrap();
        let mut offset = 0;
        let mut message_index = 0;
        let mut transcript_bytes = Vec::new();
        let expected = [(8, 40), (11, 445), (15, 136), (20, 36)];
        while offset < value.content.len() {
            // Every supplied tail ends at this one actual Handshake record's
            // boundary. NeedWork/ready-message boundaries do not invent records.
            let progress = reassembler
                .push_fragment(&value.content[offset..], 0, true)
                .unwrap();
            assert!(progress.consumed > 0 && progress.consumed <= work_budget);
            offset += progress.consumed;
            if progress.status == Status::MessageReady {
                let message = reassembler.message().unwrap().unwrap();
                let (kind, encoded_len) = expected[message_index];
                assert_eq!(message.message_type, kind);
                assert_eq!(message.encoded.len(), encoded_len);
                assert_eq!(message.body.len(), encoded_len - 4);
                assert_eq!(message.encoded, &payload[offset - encoded_len..offset]);
                transcript_bytes.extend_from_slice(message.encoded);
                if kind == 20 {
                    assert_eq!(offset, payload.len(), "Finished must end the record");
                }
                message_index += 1;
                reassembler.consume_message().unwrap();
            }
        }
        assert_eq!(message_index, 4);
        assert_eq!(transcript_bytes, payload);
        assert_eq!(reassembler.buffered_len(), 0);
        reassembler.check_key_change().unwrap();
        reassembler.finish_input().unwrap();
    }
    // Inner content type, tag and unused output are erased after successful open.
    assert!(plaintext[payload.len()..].iter().all(|byte| *byte == 0));
}
